from pathlib import Path
import xml.etree.ElementTree as ET,json,base64
p=Path(__file__).parent;r=p.parent;ref=r/'refs-spritecollab';d={}
def data(q):return 'data:image/png;base64,'+base64.b64encode(q.read_bytes()).decode()
for a in ET.parse(ref/'AnimData.xml').getroot().find('Anims'):
 n=a.findtext('Name');copy=a.findtext('CopyOf')
 if copy:d[n]={'copy':copy};continue
 d[n]={'w':int(a.findtext('FrameWidth')),'h':int(a.findtext('FrameHeight')),'dur':[int(x.text) for x in a.findall('Durations/Duration')],'dirs':1 if n=='Sleep' else 8,'src':data(ref/(n+'-Anim.png'))}
mega=[r/'revision-corpulence/repos-trois-quart-01.png',r/'Reprise-levitation/essai-manuel-jambe-1.png',r/'Reprise-levitation/essai-manuel-jambe-2.png',r/'revision-corpulence/Sommeil-fidele-00.png',r/'Sommeil-reprise/sommeil-02-provisoire.png',r/'Repos-reprise/idle-02-droite-provisoire.png',r/'Huit-directions/avant-gauche.png',r/'Repos-reprise/idle-02-gauche-provisoire.png']
for q in mega: assert q.is_file(),q
dataall={'animations':d,'mega':[data(q) for q in mega]}
s='''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Méga-Tsareena · toutes les animations disponibles</title><style>
*{box-sizing:border-box}body{background:#111d18;color:#eaf2e8;font:16px/1.5 system-ui;margin:0}main{max-width:1200px;margin:auto;padding:28px}h1{margin:0;font-size:clamp(24px,3vw,34px)}.subtitle{color:#bdcfbd}.warning{background:#493922;border-left:4px solid #f0bd71;padding:14px;border-radius:3px;margin:20px 0}.controls{display:flex;flex-wrap:wrap;gap:12px;align-items:end;margin:20px 0}label{display:block;font-size:13px;color:#cadbc8}select,button{display:block;font:inherit;border:1px solid #6d9178;border-radius:7px;background:#263f31;color:white;padding:9px 12px;margin-top:4px}button{cursor:pointer}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}article{background:#213329;padding:16px;border-radius:12px}h2{font-size:17px;margin:0 0 8px}.tag{font-size:12px;color:#ffe0a0}.stage{height:340px;background:#ccdcc1;border-radius:7px;overflow:hidden;display:grid;place-items:center}.stage canvas{width:100%;height:100%;image-rendering:pixelated}.info{min-height:4em;font-size:14px;color:#c6d8c7}a{color:#bee1b6}.list{display:flex;gap:8px;flex-wrap:wrap}.pill{background:#2b4737;border-radius:20px;padding:4px 10px;font-size:13px}.footer{font-size:13px;color:#b6c9b5}@media(max-width:700px){.grid{grid-template-columns:1fr}}
</style></head><body><main><h1>Les animations de Tsareena</h1><div class="subtitle">Comparateur · formes normale et Méga</div><div class="warning"><strong>Important :</strong> toutes les animations de la forme normale sont visibles. Côté Méga, trois essais sont disponibles : marche avant-droite, repos avant-droite et avant-gauche, et sommeil. Les autres animations Méga ne sont pas encore créées ; elles ne sont pas remplacées par la forme normale.</div><div class="controls"><label>Animation<select id="anim"></select></label><label>Direction<select id="dir"></select></label><button id="pause">Pause</button><button id="next">Image suivante</button></div><div class="grid"><article><h2>Tsareena normale <span class="tag">· référence SpriteCollab</span></h2><div class="stage"><canvas id="base" width="500" height="340"></canvas></div><p class="info" id="baseinfo"></p></article><article><h2>Méga-Tsareena <span class="tag">· essais, non finalisés</span></h2><div class="stage"><canvas id="mega" width="500" height="340"></canvas></div><p class="info" id="megainfo"></p></article></div><h2>Animations de référence disponibles</h2><div class="list" id="list"></div><p class="footer">Tsareena normale : SpriteCollab, crédit baronessfaron. Durées issues de AnimData.xml en soixantièmes de seconde ; Shoot utilise Charge. Sleep dispose d’une seule direction dans la source. Aucun de ces essais Méga n’est un pack PMDO prêt à intégrer.</p></main><script>
const D=__DATA__, animations=D.animations, mega=D.mega, names=['Face','Avant-droite','Droite','Arrière-droite','Dos','Arrière-gauche','Gauche','Avant-gauche'];let labels={Walk:'Marche',Attack:'Attaque',Shoot:'Tir',Kick:'Coup de pied',Sleep:'Sommeil',Hurt:'Blessure',Idle:'Repos',Swing:'Coup',Double:'Double',Hop:'Saut',Charge:'Charge',Rotate:'Rotation'};const anim=document.querySelector('#anim'),dir=document.querySelector('#dir');for(let k of Object.keys(animations)){anim.add(new Option(labels[k]+' · '+k,k));let el=document.createElement('span');el.className='pill';el.textContent=labels[k]+' ('+k+')';document.querySelector('#list').appendChild(el)}names.forEach((n,i)=>dir.add(new Option(n,i)));anim.value='Walk';dir.value='1';let images={};for(let [k,a] of Object.entries(animations))if(a.src){let im=new Image;im.src=a.src;images[k]=im}let mg=mega.map(src=>{let im=new Image;im.src=src;return im});let elapsed=0,start=performance.now(),paused=false;function entry(){let a=animations[anim.value];return animations[a.copy||anim.value]}function frameAt(ms,d){let total=d.reduce((a,b)=>a+b,0),v=ms*60/1000%total;for(let i=0;i<d.length;i++){if(v<d[i])return i;v-=d[i]}return 0}function reset(){elapsed=0;start=performance.now();dir.disabled=anim.value==='Sleep'}anim.onchange=reset;dir.onchange=reset;document.querySelector('#pause').onclick=()=>{paused=!paused;document.querySelector('#pause').textContent=paused?'Reprendre':'Pause';if(!paused)start=performance.now()-elapsed};document.querySelector('#next').onclick=()=>{paused=true;document.querySelector('#pause').textContent='Reprendre';let d=entry().dur,fr=frameAt(elapsed,d),sum=0;for(let i=0;i<=fr;i++)sum+=d[i];elapsed=(sum%d.reduce((a,b)=>a+b,0))*1000/60+.05};function draw(t){if(!paused)elapsed=t-start;let a=entry(),f=frameAt(elapsed,a.dur),k=animations[anim.value].copy||anim.value,row=a.dirs===1?0:+dir.value;let ctx=document.querySelector('#base').getContext('2d');ctx.clearRect(0,0,500,340);ctx.imageSmoothingEnabled=false;let im=images[k];if(im.complete&&im.naturalWidth){let scale=Math.min(6,320/a.h,420/a.w),w=a.w*scale,h=a.h*scale;ctx.drawImage(im,f*a.w,row*a.h,a.w,a.h,(500-w)/2,320-h,w,h)}document.querySelector('#baseinfo').textContent=labels[anim.value]+' · '+(a.dirs===1?'direction unique':names[row])+' · image '+(f+1)+'/'+a.dur.length+' · '+a.dur[f]+' ticks'+(animations[anim.value].copy?' · utilise Charge':'');let c=document.querySelector('#mega').getContext('2d');c.clearRect(0,0,500,340);c.imageSmoothingEnabled=false;let id=null,msg='';if(anim.value==='Sleep'){id=3+f;msg='Essai de sommeil : première pose préférée et seconde pose obtenue par déformation. Non finalisé.'}else if(anim.value==='Walk'&&+dir.value===1){id=[0,1,0,2][f];msg='Essai avant-droite : lévitation simulée, jambes raides, bras immobiles. Non finalisé.'}else if(anim.value==='Idle'&&(+dir.value===1||+dir.value===7)){id=+dir.value===1?[0,5][f]:[6,7][f];msg='Repos provisoire sur une vue validée : déplacement et déformation légers, bras non animés comme dans la référence. Non finalisé.'}else{msg='Animation ou direction Méga non réalisée. Aucun sprite de remplacement.'}if(id!==null&&mg[id].complete&&mg[id].naturalWidth){let m=mg[id],scale=Math.min(300/m.height,340/m.width),w=m.width*scale,h=m.height*scale,off=anim.value==='Walk'?[3,6,3,6][f]:0;c.drawImage(m,(500-w)/2,(340-h)/2-off,w,h)}else if(id===null){c.fillStyle='#243a2d';c.textAlign='center';c.font='bold 17px system-ui';c.fillText('Pas encore disponible',250,165);c.font='14px system-ui';c.fillText('pour cette animation et direction',250,188)}document.querySelector('#megainfo').textContent=msg;requestAnimationFrame(draw)}requestAnimationFrame(draw);
</script></body></html>'''
(p/'index.html').write_text(s.replace('__DATA__',json.dumps(dataall,ensure_ascii=False,separators=(',',':'))),encoding='utf8')
print('Generated',p/'index.html','size', (p/'index.html').stat().st_size,'animations',len(d))
